code_checker.agent_input_schema:
{
  "type": "object",
  "properties": {
    "question": {
      "type": "string",
      "description": "The question about maps, warps, or object coordinates in the disassembly."
    }
  },
  "required": ["question"]
}

code_checker.agent_output_schema:
{
  "type": "object",
  "properties": {
    "answer": {
      "type": "string",
      "description": "The exact coordinates and files from the disassembly."
    }
  },
  "required": ["answer"]
}
